	    AccountStatement entity = new AccountStatement();
            entity.setAccountStatementId( event.getAccountStatementId() );
            entity.setStatementNumber( event.getStatementNumber() );
            entity.setPeriodStart( event.getPeriodStart() );
            entity.setPeriodEnd( event.getPeriodEnd() );
            entity.setOpeningBalance( event.getOpeningBalance() );
            entity.setClosingBalance( event.getClosingBalance() );
            entity.setGeneratedAt( event.getGeneratedAt() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
